import{_ as t,o as d,c as o,a3 as a}from"./chunks/framework.B02wg2PO.js";const u=JSON.parse('{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"reference/configuration.md","filePath":"reference/configuration.md"}'),s={name:"reference/configuration.md"};function r(n,e,c,i,l,h){return d(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p>Saidi resolves every configurable value through one precedence chain: genuine environment → the settings/secrets store → <code>.env</code> → a built-in default. This page lists what lives where, the real keys and defaults, and which changes need a restart.</p><h2 id="where-configuration-lives-on-disk" tabindex="-1">Where configuration lives on disk <a class="header-anchor" href="#where-configuration-lives-on-disk" aria-label="Permalink to &quot;Where configuration lives on disk&quot;">​</a></h2><p>Two directories matter, and they are deliberately different things.</p><p><code>ROOT</code> is <code>process.cwd()</code> — the installed package or source checkout. The CLI (<code>bin/saidi.js</code>) chdirs here before spawning the server. Only package-relative assets are read from it: <code>.env</code>, the built client (<code>client/dist</code>), and the registry&#39;s &quot;don&#39;t register Saidi&#39;s own repo&quot; guard.</p><p><code>DATA_DIR</code> is where persistent state lives. It must sit <strong>outside</strong> the package, because a global update (<code>npm i -g …</code>) rewrites the package directory. Resolution, highest first:</p><table tabindex="0"><thead><tr><th>Order</th><th>Source</th><th>Result</th></tr></thead><tbody><tr><td>1</td><td><code>SAIDI_HOME</code></td><td><code>path.resolve(SAIDI_HOME)</code></td></tr><tr><td>2</td><td><code>SAIDI_DEV</code> set</td><td><code>ROOT</code> — a source checkout keeps state repo-local</td></tr><tr><td>3</td><td>default</td><td><code>~/.saidi</code> (via <code>os.homedir()</code>)</td></tr></tbody></table><p>Derived paths:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DATA_DIR/</span></span>
<span class="line"><span>├── config/        # settings.json (legacy/migration input; bind values read by the CLI)</span></span>
<span class="line"><span>├── memory/        # secrets.json (local-no-Mongo fallback), runs, memory files</span></span>
<span class="line"><span>└── agents/        # custom agent definitions (AGENT.md dirs, skills, mcp.json)</span></span></code></pre></div><p>In cloud mode each organisation is nested one level down — <code>DATA_DIR/orgs/&lt;orgId&gt;/</code> with its own <code>memory/</code>, <code>agents/</code>, <code>config/</code>, and <code>repos/</code>. Local mode returns the flat paths above unchanged, so existing installs need no migration.</p><div class="warning custom-block"><p class="custom-block-title"><code>SAIDI_HOME</code> and <code>SAIDI_DEV</code> are genuine-env only</p><p><code>DATA_DIR</code> is resolved at module load, <em>before</em> <code>.env</code> is parsed. A line in <code>.env</code> for <code>SAIDI_HOME</code> does nothing — export it in the shell or set it in the container. (<code>SAIDI_DEV</code> is split: the data-dir half is genuine-only, but the dev-frontend redirect <em>is</em> read from <code>.env</code> at runtime, and any value — even <code>&quot;0&quot;</code> — counts as on.)</p></div><h2 id="precedence" tabindex="-1">Precedence <a class="header-anchor" href="#precedence" aria-label="Permalink to &quot;Precedence&quot;">​</a></h2><p><code>resolvePrecedence()</code> in <code>src/orchestrator/config.ts</code> is the single place the rule lives:</p><ol><li><strong>Genuine environment</strong> — a variable the real OS/container/shell set <em>before</em> <code>.env</code> or the store loaded. Captured as a snapshot at module load, so later <code>process.env</code> mutations cannot erase the distinction. A container override is deliberate and always wins.</li><li><strong>The store</strong> — MongoDB-backed system settings and secrets (what the Settings UI writes). It must win over <code>.env</code>, otherwise a value you set in the UI is silently shadowed by a stale <code>.env</code> line.</li><li><strong><code>.env</code></strong> — a dev convenience only, read from <code>ROOT/.env</code>.</li><li><strong>The built-in default.</strong></li></ol><p>Empty or whitespace-only values are treated as absent at every layer.</p><h2 id="the-settings-store" tabindex="-1">The settings store <a class="header-anchor" href="#the-settings-store" aria-label="Permalink to &quot;The settings store&quot;">​</a></h2><p>System settings are <strong>platform-global</strong> and live as one MongoDB document (<code>SystemSettingsModel</code>, <code>_id</code> <code>system</code>). <code>initSettings()</code> hydrates an in-process cache at boot; reads are synchronous off that cache; writes go through to Mongo. Mongo is required — <code>initSettings()</code> throws without a live connection, and <code>updateSystemSettings()</code> refuses to persist.</p><p><code>config/settings.json</code> is the <strong>legacy file</strong>: <code>migrateLegacySettingsToMongo()</code> folds it in once (Mongo values win, missing legacy keys fill in), and <code>bin/saidi.js</code> still reads <code>port</code> and <code>host</code> from it to decide which URL to open. A partial file is fine — every missing key falls back to its default:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;primeModel&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;defaultBranchMode&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;new&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;defaultApproval&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;auto&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;cronTickSeconds&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">30</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;textProvider&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;claude&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;openaiRealtimeModel&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;gpt-realtime-mini&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;openaiRealtimeVoice&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;marin&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Every value is passed through <code>sanitize()</code> on load and on write: an unknown, out-of-range, or garbage value silently falls back to the default rather than being stored.</p><h3 id="bind-and-identity" tabindex="-1">Bind and identity <a class="header-anchor" href="#bind-and-identity" aria-label="Permalink to &quot;Bind and identity&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>host</code></td><td>string</td><td><code>127.0.0.1</code></td><td>Bind host for the HTTP/WebSocket server</td></tr><tr><td><code>port</code></td><td>integer 1–65535</td><td><code>4317</code></td><td>Bind port</td></tr><tr><td><code>ownerName</code></td><td>string (≤60 chars)</td><td><code>&#39;&#39;</code></td><td>What the assistant calls you; <code>&#39;&#39;</code> means not yet onboarded and prompts fall back to <code>Said</code></td></tr></tbody></table><h3 id="model-and-provider" tabindex="-1">Model and provider <a class="header-anchor" href="#model-and-provider" aria-label="Permalink to &quot;Model and provider&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>modelProvider</code></td><td><code>anthropic</code> | <code>custom</code></td><td><code>anthropic</code></td><td>The master routing choice for PRIME and every agent</td></tr><tr><td><code>customModel</code></td><td>string</td><td><code>&#39;&#39;</code></td><td>Model id sent as <code>ANTHROPIC_MODEL</code> on a custom endpoint; <code>&#39;&#39;</code> = endpoint default</td></tr><tr><td><code>primeModel</code></td><td>string</td><td><code>&#39;&#39;</code></td><td>SDK model override for PRIME&#39;s turns; <code>&#39;&#39;</code> = SDK default</td></tr><tr><td><code>textProvider</code></td><td><code>claude</code> | <code>openai-realtime</code></td><td><code>claude</code></td><td>Provider used for PRIME&#39;s typed turns</td></tr><tr><td><code>openaiRealtimeModel</code></td><td>string</td><td><code>OPENAI_REALTIME_MODEL</code> or <code>gpt-realtime-mini</code></td><td>Realtime/voice model</td></tr><tr><td><code>openaiRealtimeVoice</code></td><td>string</td><td><code>OPENAI_REALTIME_VOICE</code> or <code>marin</code></td><td>Realtime voice</td></tr></tbody></table><h3 id="pricing" tabindex="-1">Pricing <a class="header-anchor" href="#pricing" aria-label="Permalink to &quot;Pricing&quot;">​</a></h3><p>Rates are USD per 1M tokens. <code>0</code> means unpriced — <code>costUsd</code> stays <code>0</code> unless the SDK itself reports a cost. A negative or non-numeric value falls back rather than pricing spend at a nonsense figure. Cache reads bill at 10% of input.</p><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>customPriceIn</code> / <code>customPriceOut</code></td><td>number ≥0</td><td><code>0</code></td><td>Custom-endpoint token prices</td></tr><tr><td><code>voicePriceTextIn</code> / <code>voicePriceAudioIn</code></td><td>number ≥0</td><td><code>0</code></td><td>Realtime input rates — the browser holds the WebRTC leg, so the turn reports its own counts and these convert them</td></tr><tr><td><code>voicePriceTextOut</code> / <code>voicePriceAudioOut</code></td><td>number ≥0</td><td><code>0</code></td><td>Realtime output rates; audio and text are separate because realtime audio costs an order of magnitude more per token</td></tr><tr><td><code>creditsMargin</code></td><td>number ≥1</td><td><code>1</code></td><td>Multiplier applied to <code>costUsd</code> when debiting the wallet; <code>1</code> = at cost</td></tr><tr><td><code>creditsEnforce</code></td><td>boolean</td><td><code>false</code></td><td>Persisted and validated, but <strong>no production code path reads it</strong>. Wallet enforcement keys off cloud mode instead — see <a href="/docs/concepts/credits-and-usage">Credits, Usage &amp; Spend Limits</a>. Setting it has no effect today.</td></tr><tr><td><code>runCostAlertUsd</code></td><td>number ≥0</td><td><code>0</code></td><td>Emit a <code>run.cost_exceeded</code> reflex event once a run&#39;s cumulative cost crosses this; <code>0</code> = off</td></tr></tbody></table><h3 id="runs-and-execution" tabindex="-1">Runs and execution <a class="header-anchor" href="#runs-and-execution" aria-label="Permalink to &quot;Runs and execution&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>defaultExecutionMode</code></td><td><code>guided</code> | <code>autonomous</code></td><td><code>autonomous</code></td><td>Execution mode stamped onto new runs</td></tr><tr><td><code>defaultEffort</code></td><td><code>low</code> | <code>medium</code> | <code>high</code></td><td><code>medium</code></td><td>Default effort mode; the run composer can override per run</td></tr><tr><td><code>defaultBranchMode</code></td><td><code>new</code> | <code>current</code></td><td><code>new</code></td><td>Fallback policy for a project that declares none</td></tr><tr><td><code>defaultApproval</code></td><td><code>confirm</code> | <code>auto</code></td><td><code>confirm</code></td><td>Fallback approval policy for a project that declares none</td></tr><tr><td><code>requirePlanApproval</code></td><td>boolean</td><td><code>false</code></td><td>Park a guided run for plan approval before any task runs</td></tr><tr><td><code>verifyTasks</code></td><td>boolean</td><td><code>false</code></td><td>Check a completed task against its acceptance criteria before it may be marked done. Guided runs always verify; this adds it to autonomous ones</td></tr><tr><td><code>optimizationMode</code></td><td><code>off</code> | <code>shadow</code> | <code>canary</code> | <code>on</code></td><td><code>canary</code></td><td>Rollout gate for optimizations that may discard worker context or skip a command</td></tr><tr><td><code>runWorktrees</code></td><td>boolean</td><td><code>true</code></td><td>Give each run its own git worktree per project instead of sharing the repo&#39;s working tree</td></tr><tr><td><code>routeReadOnlyCheap</code></td><td>boolean</td><td><code>true</code></td><td>Route read-only <code>delegate_to_project</code> <code>mode:&#39;ask&#39;</code> delegations to the cheap tier</td></tr><tr><td><code>autoLearnPreferences</code></td><td>boolean</td><td><code>true</code></td><td>Observe operator corrections and store scoped, inspectable memory records</td></tr><tr><td><code>cronTickSeconds</code></td><td>number ≥5</td><td><code>60</code></td><td>Cron scheduler sweep interval</td></tr></tbody></table><h3 id="guards-and-limits" tabindex="-1">Guards and limits <a class="header-anchor" href="#guards-and-limits" aria-label="Permalink to &quot;Guards and limits&quot;">​</a></h3><p>Guard thresholds are clamped to <code>1…50</code>; a value below 1 would refuse the first attempt, so garbage falls back to the default instead of disarming the guard.</p><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>maxTaskAttempts</code></td><td>integer 1–50</td><td><code>3</code></td><td>Attempts one checklist task gets before the runtime escalates. A task may lower this via <code>attemptBudget</code>; nothing may raise it</td></tr><tr><td><code>maxSameTaskDispatches</code></td><td>integer 1–50</td><td><code>3</code></td><td>Dispatches of the same <code>(target, task)</code> before the runtime refuses to repeat it</td></tr><tr><td><code>maxDelegationFails</code></td><td>integer 1–50</td><td><code>3</code></td><td>Consecutive failures for one target before it leaves rotation for the rest of the run; any success resets it</td></tr><tr><td><code>turnMaxSteps</code></td><td>integer ≥0</td><td><code>80</code></td><td>Hard cap on agentic steps in a single PRIME turn (SDK <code>maxTurns</code>); <code>0</code> = off</td></tr><tr><td><code>turnMaxCostUsd</code></td><td>number ≥0</td><td><code>5</code></td><td>Hard USD ceiling for a single PRIME turn (SDK <code>maxBudgetUsd</code>); <code>0</code> = off</td></tr><tr><td><code>delegationTimeoutMinutes</code></td><td>integer ≥0</td><td><code>20</code></td><td>Wall-clock ceiling for one delegation; the delegation is aborted and reported as a timeout while the run continues. <code>0</code> = off</td></tr></tbody></table><h3 id="context-and-sessions" tabindex="-1">Context and sessions <a class="header-anchor" href="#context-and-sessions" aria-label="Permalink to &quot;Context and sessions&quot;">​</a></h3><p>Auto-compact windows are clamped to <code>20_000…2_000_000</code> tokens.</p><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>primeAutoCompactWindow</code></td><td>integer</td><td><code>200000</code></td><td>Auto-compact PRIME&#39;s main-chat session as it approaches this many tokens</td></tr><tr><td><code>workerAutoCompactWindow</code></td><td>integer</td><td><code>200000</code></td><td>Same, for a delegated agent worker&#39;s session</td></tr><tr><td><code>delegationResultCap</code></td><td>integer ≥500</td><td><code>8000</code></td><td>Max characters of a delegation result that enter PRIME&#39;s main-chat context — that context is replayed every future turn</td></tr><tr><td><code>memoryInjectCap</code></td><td>integer ≥1000</td><td><code>6000</code></td><td>Max characters of a memory file sent whole into a worker&#39;s task; a larger one is filtered to the facts relevant to the task</td></tr><tr><td><code>sessionPerTask</code></td><td>boolean</td><td><code>false</code></td><td>Start a fresh agent session at each checklist-task boundary instead of resuming one across the run</td></tr><tr><td><code>adaptiveSessions</code></td><td>boolean</td><td><code>true</code></td><td>Reset a participant at a real task boundary once its context crosses the threshold; same-task retries always retain their session</td></tr><tr><td><code>adaptiveSessionThreshold</code></td><td>integer</td><td><code>120000</code></td><td>The context size that triggers an adaptive reset</td></tr></tbody></table><h3 id="updates-and-approvals" tabindex="-1">Updates and approvals <a class="header-anchor" href="#updates-and-approvals" aria-label="Permalink to &quot;Updates and approvals&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>autoUpdate</code></td><td>boolean</td><td><code>true</code></td><td>Install updates and restart once no run is active. Ignored in cloud mode, source checkouts, and unsupervised starts</td></tr><tr><td><code>autoApprove</code></td><td>object of booleans</td><td>all <code>false</code></td><td>Per-action grants that skip a management tool&#39;s confirm card; the permission gate still applies</td></tr></tbody></table><p><code>autoApprove</code> accepts only these keys — anything else is dropped, and any non-<code>true</code> value becomes <code>false</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>create_agent · remove_agent</span></span>
<span class="line"><span>add_skill · import_skill</span></span>
<span class="line"><span>add_mcp_server · remove_mcp_server</span></span>
<span class="line"><span>add_project · remove_project · sync_projects</span></span>
<span class="line"><span>delete_cron · delete_reflex</span></span></code></pre></div><h2 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment variables&quot;">​</a></h2><h3 id="mode-paths-and-runtime" tabindex="-1">Mode, paths, and runtime <a class="header-anchor" href="#mode-paths-and-runtime" aria-label="Permalink to &quot;Mode, paths, and runtime&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>SAIDI_HOME</code></td><td>—</td><td>Data-dir override. Genuine env only</td></tr><tr><td><code>SAIDI_DEV</code></td><td>unset</td><td>Source-checkout mode: data stays repo-local (genuine env only) and the backend redirects browsers to the Vite dev server on <code>:5317</code></td></tr><tr><td><code>SAIDI_CLIENT_URL</code></td><td><code>http://&lt;hostname&gt;:5317</code></td><td>Where the backend bounces browsers when <code>SAIDI_DEV</code> is on</td></tr><tr><td><code>SAIDI_CLOUD</code></td><td>unset</td><td><code>1</code> = hosted multi-tenant cloud; anything else = local single-user. Also selects the Mongo database name</td></tr><tr><td><code>SAIDI_SUPERVISED</code></td><td>unset</td><td>Set to <code>1</code> by <code>bin/saidi.js</code>; enables the self-restart path</td></tr><tr><td><code>SAIDI_RUNTIME</code></td><td>—</td><td>Auto-update only applies when this is <code>dist</code>; a source checkout is skipped</td></tr><tr><td><code>SAIDI_AGENTS_DIR</code></td><td>the per-org agents dir</td><td>Override the agents directory</td></tr><tr><td><code>SAIDI_MARKETPLACE_ROOT</code></td><td><code>DATA_DIR</code></td><td>Override the marketplace state dir</td></tr><tr><td><code>SAIDI_UPDATE_MANIFEST_URL</code></td><td>—</td><td>Override the software-update manifest URL</td></tr><tr><td><code>PORT</code></td><td><code>4317</code></td><td>Bind port (see below)</td></tr><tr><td><code>HOST</code></td><td><code>127.0.0.1</code></td><td>Bind host (see below)</td></tr></tbody></table><h3 id="cloud-auth-effective-when-saidi-cloud-1" tabindex="-1">Cloud auth (effective when <code>SAIDI_CLOUD=1</code>) <a class="header-anchor" href="#cloud-auth-effective-when-saidi-cloud-1" aria-label="Permalink to &quot;Cloud auth (effective when \`SAIDI_CLOUD=1\`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>SAIDI_SUPERADMIN_EMAIL</code></td><td><code>&#39;&#39;</code></td><td>The operator account granted platform superadmin</td></tr><tr><td><code>SAIDI_PUBLIC_URL</code></td><td>the request origin</td><td>Public base URL for OAuth redirects and origin checks</td></tr><tr><td><code>SAIDI_MASTER_KEY</code></td><td>unset</td><td>KEK that AES-256-GCM-encrypts tenant secrets at rest. Accepts 64 hex chars, base64 of 32 bytes, or a passphrase (scrypt, N=16384). Unset = encryption off</td></tr><tr><td><code>SAIDI_GOOGLE_CLIENT_ID</code> / <code>SAIDI_GOOGLE_CLIENT_SECRET</code></td><td><code>&#39;&#39;</code></td><td>Google OAuth app credentials</td></tr><tr><td><code>SAIDI_GITHUB_CLIENT_ID</code> / <code>SAIDI_GITHUB_CLIENT_SECRET</code></td><td><code>&#39;&#39;</code></td><td>GitHub OAuth app credentials</td></tr></tbody></table><h3 id="sandbox" tabindex="-1">Sandbox <a class="header-anchor" href="#sandbox" aria-label="Permalink to &quot;Sandbox&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>SAIDI_SANDBOX</code></td><td>unset</td><td><code>1</code> runs agent workers inside the Docker sandbox</td></tr><tr><td><code>SAIDI_SANDBOX_IMAGE</code></td><td><code>saidi-sandbox:latest</code></td><td>Image tag the pool launches</td></tr><tr><td><code>SAIDI_SANDBOX_MEMORY</code></td><td><code>2g</code></td><td>Per-container memory limit</td></tr><tr><td><code>SAIDI_SANDBOX_CPUS</code></td><td><code>2</code></td><td>Per-container CPU limit</td></tr><tr><td><code>SAIDI_SANDBOX_NETWORK</code></td><td><code>bridge</code></td><td>Set to <code>host</code> for host networking</td></tr></tbody></table><p>With the sandbox off, agents run in-host; the env allow-list still withholds host secrets, but cross-org filesystem isolation needs the sandbox. If it is enabled and either the Docker daemon is unreachable or the image is missing, boot warns and Claude delegations fail until it is fixed.</p><h3 id="mail" tabindex="-1">Mail <a class="header-anchor" href="#mail" aria-label="Permalink to &quot;Mail&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>SAIDI_MAIL_DRIVER</code></td><td><code>console</code></td><td><code>console</code> logs the message; <code>resend</code> sends it</td></tr><tr><td><code>SAIDI_MAIL_FROM</code></td><td><code>Saidi &lt;noreply@localhost&gt;</code></td><td>From address for outbound mail</td></tr><tr><td><code>SAIDI_RESEND_API_KEY</code></td><td><code>&#39;&#39;</code></td><td>Required when the driver is <code>resend</code></td></tr></tbody></table><h3 id="webhooks" tabindex="-1">Webhooks <a class="header-anchor" href="#webhooks" aria-label="Permalink to &quot;Webhooks&quot;">​</a></h3><p>The five fixed sources are store-backed (see below). Any additional source is configured directly by name — <code>SAIDI_WEBHOOK_&lt;NAME&gt;_SCHEME</code> (<code>bearer</code> | <code>hmac</code> | <code>none</code>), <code>_SECRET</code>, <code>_HEADER</code> (default <code>x-signature</code>), <code>_PREFIX</code> (default <code>sha256=</code>), <code>_ENCODING</code> (<code>hex</code> | <code>base64</code>, default <code>hex</code>), and <code>_VERIFY_TOKEN</code>. Non-alphanumeric characters in the source name become underscores.</p><h3 id="marketplace-server" tabindex="-1">Marketplace server <a class="header-anchor" href="#marketplace-server" aria-label="Permalink to &quot;Marketplace server&quot;">​</a></h3><p>The marketplace runs as its own process (<code>saidi-marketplace</code>) with its own variables: <code>MARKETPLACE_PORT</code> (default <code>8787</code>), <code>MARKETPLACE_HOST</code> (<code>127.0.0.1</code>), <code>MARKETPLACE_MONGODB_URI</code> (<code>mongodb://127.0.0.1:27017/saidi_marketplace</code>), <code>MARKETPLACE_PUBLIC_URL</code> (<code>http://localhost:&lt;port&gt;</code>), <code>MARKETPLACE_ADMIN_TOKEN</code>, <code>MARKETPLACE_IP_SALT</code> (<code>saidi-marketplace</code>), <code>MARKETPLACE_GITHUB_CLIENT_ID</code> / <code>MARKETPLACE_GITHUB_CLIENT_SECRET</code>, and <code>MARKETPLACE_SEED</code> (set to <code>0</code> to skip seeding).</p><h2 id="secrets" tabindex="-1">Secrets <a class="header-anchor" href="#secrets" aria-label="Permalink to &quot;Secrets&quot;">​</a></h2><p>Credentials are a separate store: one global MongoDB document, encrypted at rest with envelope AES-256-GCM under <code>SAIDI_MASTER_KEY</code> whenever that key is set. Cloud mode requires the key; local mode keeps it optional and stores the document plaintext, the same trust level as the gitignored <code>memory/secrets.json</code> it replaced. Cloud never writes secrets to disk.</p><p>Each field maps to the environment variable the SDKs actually read, and <code>hydrateEnvFromSecrets()</code> pushes the resolved value into <code>process.env</code> at boot so the app runs with no <code>.env</code> while a container override still wins:</p><table tabindex="0"><thead><tr><th>Field</th><th>Environment variable</th></tr></thead><tbody><tr><td><code>mongodbUri</code></td><td><code>MONGODB_URI</code></td></tr><tr><td><code>anthropicModel</code></td><td><code>ANTHROPIC_MODEL</code></td></tr><tr><td><code>anthropicBaseUrl</code></td><td><code>ANTHROPIC_BASE_URL</code></td></tr><tr><td><code>anthropicApiKey</code></td><td><code>ANTHROPIC_API_KEY</code></td></tr><tr><td><code>anthropicAuthToken</code></td><td><code>ANTHROPIC_AUTH_TOKEN</code></td></tr><tr><td><code>claudeCodeOauthToken</code></td><td><code>CLAUDE_CODE_OAUTH_TOKEN</code></td></tr><tr><td><code>openaiApiKey</code></td><td><code>OPENAI_API_KEY</code></td></tr><tr><td><code>saidiGithubToken</code></td><td><code>SAIDI_GITHUB_TOKEN</code></td></tr><tr><td><code>webhookGenericToken</code></td><td><code>SAIDI_WEBHOOK_GENERIC_TOKEN</code></td></tr><tr><td><code>webhookGithubSecret</code></td><td><code>SAIDI_WEBHOOK_GITHUB_SECRET</code></td></tr><tr><td><code>webhookStripeSecret</code></td><td><code>SAIDI_WEBHOOK_STRIPE_SECRET</code></td></tr><tr><td><code>webhookMetaSecret</code></td><td><code>SAIDI_WEBHOOK_META_SECRET</code></td></tr><tr><td><code>webhookMetaVerifyToken</code></td><td><code>SAIDI_WEBHOOK_META_VERIFY_TOKEN</code></td></tr></tbody></table><p><code>MONGODB_URI</code> is the one exception: it is bootstrap config — how the process reaches Mongo — so it is never persisted to Mongo and resolves from genuine env or <code>.env</code> only.</p><h2 id="model-provider-configuration" tabindex="-1">Model provider configuration <a class="header-anchor" href="#model-provider-configuration" aria-label="Permalink to &quot;Model provider configuration&quot;">​</a></h2><p><code>modelProvider</code> is one choice that routes the whole system, and <code>applyModelProviderEnv()</code> makes it real by pinning the ambient Anthropic variables every Claude SDK call reads:</p><table tabindex="0"><thead><tr><th><code>modelProvider</code></th><th>Set</th><th>Unset</th></tr></thead><tbody><tr><td><code>custom</code></td><td><code>ANTHROPIC_BASE_URL</code>, <code>ANTHROPIC_AUTH_TOKEN</code>, <code>ANTHROPIC_MODEL</code> = <code>customModel</code>, and every family alias = <code>customModel</code></td><td><code>ANTHROPIC_API_KEY</code>, <code>CLAUDE_CODE_OAUTH_TOKEN</code></td></tr><tr><td><code>anthropic</code></td><td><code>ANTHROPIC_API_KEY</code>, <code>CLAUDE_CODE_OAUTH_TOKEN</code>, <code>ANTHROPIC_MODEL</code></td><td><code>ANTHROPIC_BASE_URL</code>, <code>ANTHROPIC_AUTH_TOKEN</code>, all family aliases</td></tr></tbody></table><p>The family aliases are <code>ANTHROPIC_DEFAULT_OPUS_MODEL</code>, <code>ANTHROPIC_DEFAULT_SONNET_MODEL</code>, <code>ANTHROPIC_DEFAULT_HAIKU_MODEL</code>, <code>ANTHROPIC_DEFAULT_FABLE_MODEL</code>, and <code>ANTHROPIC_SMALL_FAST_MODEL</code>. They exist because <code>ANTHROPIC_MODEL</code> only sets the session default — a nested sub-agent that asks for <code>sonnet</code> or <code>opus</code> by family would otherwise request an Anthropic model id from an endpoint that serves only its own.</p><div class="warning custom-block"><p class="custom-block-title">This override beats a genuine env var</p><p><code>applyModelProviderEnv()</code> deliberately overwrites even a real container environment value for those variables. Picking a provider in Settings is an explicit instruction about which endpoint to use, and a half-applied mix (custom base URL plus official key) is worse than either. Set a custom endpoint in Settings, not as <code>ANTHROPIC_BASE_URL</code> in your compose file.</p></div><h2 id="ports-and-hosts" tabindex="-1">Ports and hosts <a class="header-anchor" href="#ports-and-hosts" aria-label="Permalink to &quot;Ports and hosts&quot;">​</a></h2><p><code>getPort()</code> and <code>getHost()</code> resolve genuine env → the store → <code>.env</code> → default. The port is validated at every layer: a value that is not an integer in <code>1…65535</code> is skipped and the next layer is tried, ending at <code>4317</code>. The host defaults to <code>127.0.0.1</code> — localhost only.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Bind to all interfaces on a non-default port for this process only</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HOST</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">0.0.0.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PORT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">8080</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><p>Bind settings are injected into the config module from the hydrated settings cache immediately before <code>listen()</code>, so a value saved in Settings is what the next boot binds to.</p><p>The <code>saidi</code> CLI reads <code>port</code> and <code>host</code> from <code>config/settings.json</code> directly (with env still winning) so it can wait for the socket and open the right browser URL without importing server config. When <code>SAIDI_DEV</code> is on, the one app URL is the Vite dev server at <code>:5317</code>; this process is only the API and WebSocket origin its proxy forwards to.</p><h2 id="database-and-storage" tabindex="-1">Database and storage <a class="header-anchor" href="#database-and-storage" aria-label="Permalink to &quot;Database and storage&quot;">​</a></h2><p>MongoDB is required. There is deliberately no degraded file-backed mode and no background late-connect path.</p><ul><li><strong>Server</strong> — from <code>resolveSecret(&#39;mongodbUri&#39;)</code>, falling back to <code>mongodb://127.0.0.1:27017</code>. Host, credentials, and options all come from here.</li><li><strong>Database name</strong> — derived from <code>SAIDI_CLOUD</code>: <code>saidi_cloud</code> when <code>1</code>, otherwise <code>saidi</code>. <code>withDatabase()</code> <em>replaces</em> whatever database the configured URI carries, so one stored server serves both modes. Do not put a database name in the URI.</li><li><strong>Connect timeout</strong> — <code>serverSelectionTimeoutMS: 2500</code>.</li><li><strong>Failure</strong> — a failed connect at boot is fatal (<code>exit 1</code>). A later <code>disconnected</code> event terminates the process after a 1s grace period rather than accepting non-durable changes; a supervisor restarts it so every in-memory working set is rebuilt from the authoritative snapshot.</li></ul><p>Structured records (runs, activity, settings, secrets, channel config) live in Mongo. Human-editable markdown memory and the scanned project registry stay as files, mirrored under <code>memory/</code>, because they are meant to be inspected and edited on disk. See <a href="/docs/concepts/runs">Runs</a> for what a run persists.</p><h2 id="changing-configuration-safely" tabindex="-1">Changing configuration safely <a class="header-anchor" href="#changing-configuration-safely" aria-label="Permalink to &quot;Changing configuration safely&quot;">​</a></h2><p><strong>Takes effect immediately.</strong> Anything read through <code>getSystemSettings()</code> on each use — guards, caps, execution defaults, approval toggles. <code>updateSystemSettings()</code> merges, sanitizes, replaces the in-process cache, and writes through to Mongo. The settings route also calls <code>applyModelProviderEnv()</code> on every save, so a provider or custom-model change applies to the next call without a restart.</p><p><strong>Needs a fresh boot.</strong> A new <code>MONGODB_URI</code> (the Mongoose connection is opened once at startup), re-hydrating env from the secret store, reloading the agent catalog after an import, and a changed <code>host</code>/<code>port</code> (they persist to Mongo but only bind on the next <code>listen()</code>).</p><p>Rather than asking you to restart by hand, those routes call <code>requestRestart()</code> after the response is flushed. The process exits with code <code>75</code> and the supervisor in <code>bin/saidi.js</code> relaunches it — the old child fully exits first, so the port is released before the new one binds. The auto-update path uses code <code>76</code>, which tells the supervisor to run the global install <em>between</em> spawns (<code>npm i -g</code> rewrites the very directory the process executes from).</p><div class="warning custom-block"><p class="custom-block-title">Self-restart only works under the supervisor</p><p><code>requestRestart()</code> is a no-op returning <code>false</code> unless <code>SAIDI_SUPERVISED=1</code>. Started directly with <code>npm start</code> or <code>node dist/server.js</code>, nothing would bring the process back, so the route reports that you must restart manually. The settings save response includes a <code>restarting</code> flag so you can tell which happened.</p></div><p>Shutdown is graceful in both paths: channels and the reflex engine stop, sandbox containers are disposed, dashboard WebSockets are force-closed first (a long-lived <code>/ws</code> socket would otherwise hang <code>server.close()</code>), then debounced activity and run writes are drained before the Mongo connection drops.</p><h2 id="verifying-what-actually-resolved" tabindex="-1">Verifying what actually resolved <a class="header-anchor" href="#verifying-what-actually-resolved" aria-label="Permalink to &quot;Verifying what actually resolved&quot;">​</a></h2><p>The server prints a resolved-configuration summary at boot — mode and paths, the bind URL, the redacted Mongo URI, the active model provider, voice settings, cloud auth (in cloud mode), sandbox and supervision state, and mail/webhook credentials. Each row is tagged with where the value came from: <code>shell env</code>, <code>store</code>, <code>.env</code>, or <code>default</code>. Secrets are masked to their last three characters and connection URIs have credentials redacted.</p><p>Start there when a value is not what you expect — it turns the precedence rules into something you can read instead of guess.</p><p>See also: <a href="/docs/reference/settings">Settings</a> · <a href="/docs/operations/deployment">Deployment</a> · <a href="/docs/operations/troubleshooting">Troubleshooting</a></p>`,82)])])}const g=t(s,[["render",r]]);export{u as __pageData,g as default};
